API: GetEntitiesWithMetrics
query {
  entity_list { entity_type_name: "vm" }
  where_clause {
    comparison_expr {
      lhs {
        leaf {
          column: "vm_name"
        }
      }
      operator: kLike
      rhs {
        value { str_value: ".*prod.*" }
      }
    }
  }
  where_clause {
    comparison_expr {
      lhs {
        leaf {
          column: "power_state"
        }
      }
      operator: kEQ
      rhs {
        value {
          str_value: "on"
        }
      }
    }
  }
  group_by {
    raw_columns { column: "vm_name" }
  }
  query_name: "auto_query"
}

